-- SELECT granted once, on the schema
GRANT SELECT ON SCHEMA finance.accounts_payable
  TO `data-analysts`;

-- A table created LATER is readable immediately —
-- no new GRANT required
CREATE TABLE finance.accounts_payable.new_vendor_report (...);

-- MANAGE on a catalog: no usage privilege needed at all
GRANT MANAGE ON CATALOG finance TO `platform-admins`;

-- MANAGE on a schema still needs USE CATALOG on its parent
GRANT USE CATALOG ON CATALOG finance TO `schema-admins`;
GRANT MANAGE ON SCHEMA finance.accounts_payable
  TO `schema-admins`;
